import { HttpClient } from '@angular/common/http';
import { Component, Injectable, effect, inject, signal, untracked } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from '../../core/session';

export interface RoleView {
  user: string;
  role: string;
}

interface SettingsView {
  // The most a clerk may settle a claim for; null for no limit.
  clerkLimit: string | null;
}

export const ROLES = ['clerk', 'steward'];

const LIMIT = /^\d{1,12}(\.\d{1,2})?$/;

// The active sheet's settings: the role set for each user name (any other name is a clerk) and the clerk limit.
@Injectable({ providedIn: 'root' })
export class SettingsStore {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  readonly roles = signal<readonly RoleView[]>([]);
  readonly clerkLimit = signal<string | null>(null);

  /** Re-read the sheet's settings from the store. */
  async load(sheet: string): Promise<void> {
    this.roles.set([]);
    this.clerkLimit.set(null);
    const base = `/api/sheets/${encodeURIComponent(sheet)}`;
    const [roles, settings] = await Promise.all([
      firstValueFrom(this.http.get<RoleView[]>(`${base}/roles`)),
      firstValueFrom(this.http.get<SettingsView>(`${base}/settings`)),
    ]);
    if (this.session.sheetId() === sheet) {
      this.roles.set(roles);
      this.clerkLimit.set(settings.clerkLimit);
    }
  }

  async setRole(sheet: string, user: string, role: string): Promise<void> {
    const r = await firstValueFrom(
      this.http.put<RoleView>(`/api/sheets/${encodeURIComponent(sheet)}/roles/${encodeURIComponent(user)}`, { role }),
    );
    if (this.session.sheetId() === sheet) {
      this.roles.update((l) => [...l.filter((x) => x.user !== r.user), r].sort((a, b) => a.user.localeCompare(b.user)));
    }
  }

  async setClerkLimit(sheet: string, value: string | null): Promise<void> {
    const s = await firstValueFrom(
      this.http.put<SettingsView>(`/api/sheets/${encodeURIComponent(sheet)}/settings/clerk-limit`, { value }),
    );
    if (this.session.sheetId() === sheet) this.clerkLimit.set(s.clerkLimit);
  }
}

// The sheet's settings: the clerk limit, and the role each user name has.
@Component({
  selector: 'app-settings',
  template: `
    <section aria-label="Settings">
      <h2>Settings</h2>
      <form (submit)="saveSettings($event)" aria-label="Save settings">
        <label for="setting-clerk-limit">Clerk limit (blank for none)</label>
        <input
          id="setting-clerk-limit"
          data-testid="setting-clerk-limit"
          inputmode="decimal"
          [value]="limit()"
          (input)="limit.set(value($event)); settingsError.set(null)"
        />
        <button type="submit" data-testid="settings-save">Save settings</button>
        @if (settingsError(); as err) {
          <p role="alert" data-testid="settings-error">{{ err }}</p>
        }
      </form>
      <p>Clerk limit in force: <strong data-testid="setting-clerk-limit-current">{{ store.clerkLimit() ?? '' }}</strong></p>

      <form (submit)="saveRole($event)" aria-label="Set role">
        <label for="role-user">User name</label>
        <input
          id="role-user"
          data-testid="role-form-user"
          [value]="user()"
          (input)="user.set(value($event)); roleError.set(null)"
        />
        <label for="role-role">Role (clerk or steward)</label>
        <input
          id="role-role"
          data-testid="role-form-role"
          list="role-options"
          [value]="role()"
          (input)="role.set(value($event)); roleError.set(null)"
        />
        <datalist id="role-options">
          @for (r of roles; track r) {
            <option [value]="r"></option>
          }
        </datalist>
        <button type="submit" data-testid="role-form-submit">Set role</button>
        @if (roleError(); as err) {
          <p role="alert" data-testid="role-form-error">{{ err }}</p>
        }
      </form>

      <table>
        <caption>Roles (any other name is a clerk)</caption>
        <thead>
          <tr><th scope="col">User</th><th scope="col">Role</th></tr>
        </thead>
        <tbody>
          @for (r of store.roles(); track r.user) {
            <tr [attr.data-testid]="'role-row-' + r.user">
              <th scope="row" data-testid="role-user">{{ r.user }}</th>
              <td data-testid="role-value">{{ r.role }}</td>
            </tr>
          }
        </tbody>
      </table>
    </section>
  `,
})
export class Settings {
  protected readonly session = inject(Session);
  protected readonly store = inject(SettingsStore);

  protected readonly roles = ROLES;
  protected readonly limit = signal('');
  protected readonly user = signal('');
  protected readonly role = signal('');
  protected readonly settingsError = signal<string | null>(null);
  protected readonly roleError = signal<string | null>(null);
  // A submit in flight: a second submit before it answers is ignored.
  private submitting = false;

  constructor() {
    // Re-read the settings from the store each time a sheet is loaded.
    effect(() => {
      const id = this.session.sheetId();
      this.session.loads();
      untracked(() => {
        this.settingsError.set(null);
        this.roleError.set(null);
        if (id) this.store.load(id).catch(() => this.settingsError.set('Could not load the settings.'));
      });
    });
  }

  protected value(e: Event): string {
    return (e.target as HTMLInputElement).value;
  }

  protected async saveSettings(e: Event): Promise<void> {
    e.preventDefault();
    if (this.submitting) return;
    this.settingsError.set(null);
    const sheet = this.session.sheetId();
    if (!sheet) return;
    const limit = this.limit().trim();
    if (limit && !LIMIT.test(limit)) {
      this.settingsError.set('Enter a clerk limit of 0.00 or more, with up to two decimals, or leave it blank.');
      return;
    }
    this.submitting = true;
    try {
      await this.store.setClerkLimit(sheet, limit || null);
    } catch {
      this.settingsError.set('Could not save the settings.');
    } finally {
      this.submitting = false;
    }
  }

  protected async saveRole(e: Event): Promise<void> {
    e.preventDefault();
    if (this.submitting) return;
    this.roleError.set(null);
    const sheet = this.session.sheetId();
    if (!sheet) return;
    const user = this.user().trim();
    const role = this.role().trim();
    if (!user) {
      this.roleError.set('Enter a user name.');
      return;
    }
    if (!ROLES.includes(role)) {
      this.roleError.set('Choose a role of clerk or steward.');
      return;
    }
    this.submitting = true;
    try {
      await this.store.setRole(sheet, user, role);
    } catch {
      this.roleError.set('Could not set that role.');
    } finally {
      this.submitting = false;
    }
  }
}
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Component, inject, input, output, signal } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from '../../core/session';
import { PeriodStore, inClosedPeriod, periodOn } from '../periods/periods';
import { RateView, dueOn, rateOn } from '../rates/rates';

export interface Claim {
  id: number;
  personId: number;
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  // Given when the claim is opened; null for a draft or voided claim.
  number: number | null;
  // The due fixed when the claim was settled; null while its due is live.
  settledDue: string | null;
  // The user who opened the claim; null for a claim never opened. That user cannot settle it.
  openedBy: string | null;
  // Whether the person's last statement binds the claim, and the figure it binds it to (null for n/a).
  stated: boolean;
  statedDue: string | null;
}

export type ClaimStatus = 'DRAFT' | 'OPEN' | 'SETTLED' | 'VOID';

type ClaimAction = 'open' | 'settle' | 'void';

/** Only open and settled claims count toward what is claimed and due. */
export function counts(c: Claim): boolean {
  return c.status === 'OPEN' || c.status === 'SETTLED';
}

/**
 * The figure a claim shows and totals: its settled due, else the one a statement bound it to, else its live due
 * at the rate in force on its date; null (n/a) with none.
 */
export function figureOf(c: Claim, rates: readonly RateView[]): string | null {
  if (c.settledDue !== null) return c.settledDue;
  return c.stated ? c.statedDue : dueOn(c.amount, rateOn(rates, c.date));
}

/** Whether the claim keeps a figure whatever the rates: a settled or stated one with a figure. */
export function keepsFigure(c: Claim): boolean {
  return c.settledDue !== null || (c.stated && c.statedDue !== null);
}

const CLOSED = 'That claim is dated in a closed period, so it cannot change.';

export const AMOUNT = /^\d+(\.\d{1,2})?$/;

/** The sum of the counted claims' amounts, with two decimals; added in whole cents so nothing drifts. */
export function claimedTotal(claims: readonly Claim[]): string {
  const cents = claims.filter(counts).reduce((sum, c) => sum + Math.round(Number(c.amount) * 100), 0);
  return (cents / 100).toFixed(2);
}

// One person's claims, newest first: one form adds a claim or, with a claim's editor open, saves it.
@Component({
  selector: 'app-claims',
  template: `
    <form (submit)="submit($event)" [attr.aria-label]="(editingId() === null ? 'Add claim for ' : 'Edit claim for ') + personName()">
      <label [for]="'claim-amount-' + personId()">Amount</label>
      <input
        [id]="'claim-amount-' + personId()"
        data-testid="claim-form-amount"
        inputmode="decimal"
        [value]="amount()"
        (input)="amount.set(value($event)); error.set(null)"
      />
      <label [for]="'claim-date-' + personId()">Date</label>
      <input
        [id]="'claim-date-' + personId()"
        type="date"
        data-testid="claim-form-date"
        [value]="date()"
        (input)="date.set(value($event)); error.set(null)"
      />
      <label [for]="'claim-note-' + personId()">Note</label>
      <input
        [id]="'claim-note-' + personId()"
